//! The one place a handle's surface is stated, for mlua and for the checker.
//!
//! Luau resolves `require '@lunette'` to a file on disk. A definitions file
//! declares globals and nothing else, so the module needs Luau source of its
//! own: `lua/lunette/init.luau`, generated by `lunette-generate-definitions`.
//!
//! A field is declared once, by [`handle!`], where it is registered.
//! [`Described::describe`] then runs against two [`Surface`] implementations:
//! one forwards to mlua, the other keeps the names, the prose, and the types
//! and drops the closures. The types derive from the Rust signatures through
//! [`Typed`], so a signature cannot be restated wrongly.

mod macros;
mod render;
mod types;

use std::marker::PhantomData;

pub use lunette_luau::{Arguments, Parameter, Type, Typed, of};
use mlua::{
    FromLua, FromLuaMulti, IntoLua, IntoLuaMulti, Lua, MaybeSend, Table, UserDataFields,
    UserDataMethods, Value,
};

pub(crate) use crate::lua::declarations::{
    macros::{handle, module, record},
    render::render_doc,
};
pub use crate::lua::declarations::{
    render::render,
    types::{Nil, Textured},
};
use crate::{
    control::{serialise::HANDLE_METAFIELD, wire::HandleKind},
    lua::{LuaTexture, reject_unknown_options},
    texture::CopyableTexture,
};

/// A handle whose surface is stated once and read two ways.
pub trait Described: Sized + Typed {
    const HANDLE: HandleSpec;

    /// What `lunctl` recognises the handle by.
    const KIND: HandleKind;

    /// Declares every property and method, in the order the file states them.
    fn describe(surface: &mut impl Surface<Self>);
}

/// Where a method declaration goes: into mlua, or into the generated Luau.
pub trait MethodSurface<T: Typed> {
    fn method<M, A, R>(&mut self, spec: MethodSpec, body: M)
    where
        M: Fn(&Lua, &T, A) -> mlua::Result<R> + MaybeSend + 'static,
        A: FromLuaMulti + Arguments,
        R: IntoLuaMulti + Typed;
}

/// A type whose userdata methods and generated method declarations share one body.
pub trait MethodsDescribed: Typed + Sized {
    fn describe_methods(surface: &mut impl MethodSurface<Self>);
}

/// Where a declaration goes: into mlua, or into the generated Luau.
pub trait Surface<T: Described + Typed>: MethodSurface<T> {
    fn field<G, R>(&mut self, spec: FieldSpec, get: G)
    where
        G: Fn(&Lua, &T) -> mlua::Result<R> + MaybeSend + 'static,
        R: IntoLua + Typed;
}

/// Registers a handle's properties with mlua.
pub fn add_fields<T, F>(fields: &mut F)
where
    T: Described + Typed + 'static,
    F: UserDataFields<T>,
{
    fields.add_meta_field(HANDLE_METAFIELD, T::KIND.as_str());
    T::describe(&mut FieldRegistrar {
        fields,
        handle: PhantomData,
    });
}

/// Registers a handle's methods with mlua.
pub fn add_methods<T, M>(methods: &mut M)
where
    T: Described + Typed + 'static,
    M: UserDataMethods<T>,
{
    T::describe(&mut MethodRegistrar {
        methods,
        handle: PhantomData,
    });
}

/// Registers a type's described methods with mlua.
pub fn add_described_methods<T, M>(methods: &mut M)
where
    T: MethodsDescribed + 'static,
    M: UserDataMethods<T>,
{
    T::describe_methods(&mut MethodRegistrar {
        methods,
        handle: PhantomData,
    });
}

/// A handle's own line in the generated file.
#[derive(Clone, Copy, Debug)]
pub struct HandleSpec {
    pub name: &'static str,
    pub doc: &'static str,
    /// The arms of a handle discriminated on one of its fields, in the order a
    /// [`FieldType::PerVariant`] names their types. Empty for a plain handle.
    pub variants: &'static [&'static str],
}

/// A property.
#[derive(Clone, Copy, Debug)]
pub struct FieldSpec {
    pub name: &'static str,
    pub doc: &'static str,
    pub ty: FieldType,
}

/// Where a property's Luau type comes from.
#[derive(Clone, Copy, Debug)]
pub enum FieldType {
    /// From the Rust type the getter answers with. This is the usual case.
    Derived,
    /// One type per arm. A single getter serves the two views of one field.
    PerVariant(&'static [fn() -> Type]),
}

/// A method. Every parameter but the receiver is named, and the names are the
/// bindings its body uses.
#[derive(Clone, Copy, Debug)]
pub struct MethodSpec {
    pub name: &'static str,
    pub doc: &'static str,
    pub receiver: Receiver,
    pub parameters: &'static [&'static str],
}

/// What a method's first parameter is called.
#[derive(Clone, Copy, Debug)]
pub enum Receiver {
    /// The handle the method is declared on.
    Own,
    /// A wider type, for a method reached through a union.
    Named(fn() -> Type),
}

/// A function on the module table.
#[derive(Clone, Copy, Debug)]
pub struct FunctionSpec {
    pub name: &'static str,
    pub doc: &'static str,
}

/// A table of writable fields: an option table a call accepts, or a value the
/// runtime hands over.
#[derive(Clone, Copy, Debug)]
pub struct Record {
    pub name: &'static str,
    pub doc: &'static str,
    pub fields: &'static [RecordField],
}

impl Record {
    pub fn names(&self) -> impl Iterator<Item = &'static str> {
        self.fields.iter().map(|field| field.name)
    }
}

#[derive(Clone, Copy, Debug)]
pub struct RecordField {
    pub name: &'static str,
    pub doc: &'static str,
    pub ty: fn() -> Type,
}

/// A type the generated file states as a table of plain fields.
pub trait Recorded {
    const RECORD: Record;
}

/// An option table as an argument, checked on the way in.
///
/// The unknown-option check runs here. A table that reaches a method body is
/// one the declaration accounts for.
#[derive(Debug)]
pub struct Options<S: Recorded> {
    table: Table,
    shape: PhantomData<S>,
}

impl<S: Recorded> Options<S> {
    #[must_use]
    pub fn table(&self) -> &Table {
        &self.table
    }
}

impl<S: Recorded> FromLua for Options<S> {
    fn from_lua(value: Value, lua: &Lua) -> mlua::Result<Self> {
        let table = Table::from_lua(value, lua)?;
        reject_unknown_options(&table, &S::RECORD)?;
        Ok(Self {
            table,
            shape: PhantomData,
        })
    }
}

impl<S: Recorded> Typed for Options<S> {
    fn luau() -> Type {
        Type::Named(S::RECORD.name)
    }
}

/// The texture the declaration walk instantiates the handles with. Never handed
/// a value: collecting a handle's declarations calls none of its closures.
#[derive(Clone, Copy, Debug)]
pub struct NullTexture;

impl LuaTexture for NullTexture {
    fn push(&self, _: &Lua) -> mlua::Result<Value> {
        Ok(Value::Nil)
    }
}

impl CopyableTexture for NullTexture {
    fn allocate_copy(&self) -> Option<Self> {
        None
    }

    fn copy_to(&self, _: &Self) -> bool {
        false
    }
}

/// What one handle declared, with its types resolved.
#[derive(Debug)]
pub struct Handle {
    pub spec: HandleSpec,
    pub fields: Vec<Property>,
    pub methods: Vec<Signature>,
}

/// A type the generated file states as an `export type`, not as a handle or a
/// record.
///
/// Declared beside the Rust type that stands for it, so what an alias is
/// called, what it means, and what it is made of are one thing. The renderer
/// states which aliases to emit; the checker catches an alias that is left
/// out, because a declaration that refers to a type nothing declares does not
/// typecheck.
#[derive(Clone, Copy, Debug)]
pub struct AliasSpec {
    pub doc: &'static str,
    /// What the alias is called. The name comes from the Rust type's own
    /// [`Typed`] impl.
    pub name: fn() -> Type,
    /// What it stands for. It receives the collected handles, because an alias
    /// over them is read from their declarations.
    pub definition: fn(&[&Handle]) -> Type,
}

/// A Rust type that the generated file states as an alias.
pub trait Aliased {
    const ALIAS: AliasSpec;
}

/// A property, as the generated file states it.
#[derive(Debug)]
pub struct Property {
    pub name: &'static str,
    pub doc: &'static str,
    pub ty: PropertyType,
}

#[derive(Debug)]
pub enum PropertyType {
    Same(Type),
    PerVariant(Vec<Type>),
}

/// A method, as the generated file states it.
#[derive(Debug)]
pub struct Signature {
    pub name: &'static str,
    pub doc: &'static str,
    pub ty: Type,
}

/// Walks a handle's declarations without a Lua state.
#[must_use]
pub fn collect<T: Described + Typed>() -> Handle {
    let mut collector = Collector::default();
    T::describe(&mut collector);
    Handle {
        spec: T::HANDLE,
        fields: collector.fields,
        methods: collector.methods,
    }
}

/// Collects a type's method declarations without a Lua state.
#[must_use]
pub fn collect_methods<T: MethodsDescribed>() -> Vec<Signature> {
    let mut collector = Collector::default();
    T::describe_methods(&mut collector);
    collector.methods
}

/// Builds the Luau type of a function from what it takes and answers.
///
/// `receiver` is the first parameter where there is one. Every method has a
/// receiver; no module function does.
pub(crate) fn function_type(
    receiver: Option<Type>,
    parameters: &[&'static str],
    arguments: &[Type],
    returns: Type,
) -> Type {
    Type::Function {
        receiver: receiver.map(Box::new),
        parameters: parameters
            .iter()
            .zip(arguments)
            .map(|(name, ty)| Parameter {
                name,
                ty: ty.clone(),
            })
            .collect(),
        returns: Box::new(returns),
    }
}

/// Forwards a handle's properties to mlua, ignoring its methods.
///
/// Two registrars exist because mlua takes fields and methods through separate
/// callbacks; each pass drops what the other collects.
struct FieldRegistrar<'a, T, F> {
    fields: &'a mut F,
    handle: PhantomData<T>,
}

impl<T: Described + Typed, F: UserDataFields<T>> Surface<T> for FieldRegistrar<'_, T, F> {
    fn field<G, R>(&mut self, spec: FieldSpec, get: G)
    where
        G: Fn(&Lua, &T) -> mlua::Result<R> + MaybeSend + 'static,
        R: IntoLua + Typed,
    {
        self.fields.add_field_method_get(spec.name, get);
    }
}

impl<T: Typed, F: UserDataFields<T>> MethodSurface<T> for FieldRegistrar<'_, T, F> {
    fn method<M, A, R>(&mut self, _: MethodSpec, _: M)
    where
        M: Fn(&Lua, &T, A) -> mlua::Result<R> + MaybeSend + 'static,
        A: FromLuaMulti + Arguments,
        R: IntoLuaMulti + Typed,
    {
    }
}

/// Forwards a handle's methods to mlua, ignoring its properties.
struct MethodRegistrar<'a, T, M> {
    methods: &'a mut M,
    handle: PhantomData<T>,
}

impl<T: Described + Typed, Registry: UserDataMethods<T>> Surface<T>
    for MethodRegistrar<'_, T, Registry>
{
    fn field<G, R>(&mut self, _: FieldSpec, _: G)
    where
        G: Fn(&Lua, &T) -> mlua::Result<R> + MaybeSend + 'static,
        R: IntoLua + Typed,
    {
    }
}

impl<T: Typed, Registry: UserDataMethods<T>> MethodSurface<T> for MethodRegistrar<'_, T, Registry> {
    fn method<M, A, R>(&mut self, spec: MethodSpec, body: M)
    where
        M: Fn(&Lua, &T, A) -> mlua::Result<R> + MaybeSend + 'static,
        A: FromLuaMulti + Arguments,
        R: IntoLuaMulti + Typed,
    {
        self.methods.add_method(spec.name, body);
    }
}

/// Resolves the declarations into what the file says.
#[derive(Debug, Default)]
struct Collector {
    fields: Vec<Property>,
    methods: Vec<Signature>,
}

impl<T: Described + Typed> Surface<T> for Collector {
    fn field<G, R>(&mut self, spec: FieldSpec, _: G)
    where
        G: Fn(&Lua, &T) -> mlua::Result<R> + MaybeSend + 'static,
        R: IntoLua + Typed,
    {
        self.fields.push(Property {
            name: spec.name,
            doc: spec.doc,
            ty: match spec.ty {
                FieldType::Derived => PropertyType::Same(R::luau()),
                FieldType::PerVariant(arms) => {
                    PropertyType::PerVariant(arms.iter().map(|arm| arm()).collect())
                }
            },
        });
    }
}

impl<T: Typed> MethodSurface<T> for Collector {
    fn method<M, A, R>(&mut self, spec: MethodSpec, _: M)
    where
        M: Fn(&Lua, &T, A) -> mlua::Result<R> + MaybeSend + 'static,
        A: FromLuaMulti + Arguments,
        R: IntoLuaMulti + Typed,
    {
        let receiver = match spec.receiver {
            Receiver::Own => T::luau(),
            Receiver::Named(named) => named(),
        };
        self.methods.push(Signature {
            name: spec.name,
            doc: spec.doc,
            ty: function_type(Some(receiver), spec.parameters, &A::luau(), R::luau()),
        });
    }
}
